<template><view class="page"><view class="bar"><text @tap="back">‹</text><text>{{ postId ? '编辑博客' : '新建博客' }}</text><text @tap="save">保存</text></view><scroll-view class="scroll" scroll-y><view class="content"><input v-model="form.title" class="input title" placeholder="博客标题"/><picker :range="categoryNames" @change="chooseCategory"><view class="picker">{{ selectedCategoryName }}</view></picker><textarea v-model="form.content" class="textarea" auto-height maxlength="50000" placeholder="开始写作，支持 Markdown…"/><ImageUploadGrid v-model="images" @change="syncImages"/><view class="switch-row"><text>公开显示</text><switch :checked="form.is_public" color="#1d6347" @change="form.is_public=$event.detail.value"/></view><view class="switch-row"><text>立即发布</text><switch :checked="form.is_published" color="#1d6347" @change="form.is_published=$event.detail.value"/></view><text class="hint">关闭“公开显示”或“立即发布”会保留为个人草稿；超级管理员可修改全站文章。</text><button class="primary" :loading="saving" @tap="save">{{ postId ? '保存修改' : '创建博客' }}</button></view></scroll-view></view></template>
<script>
import { createMyBlogPost, getBlogCategories, getMyBlogPosts, updateMyBlogPost } from '../../services/api'
import ImageUploadGrid from '../../components/ImageUploadGrid.vue'
function slug(title) { return 'android-' + Date.now() + '-' + (String(title || 'post').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 40) || 'post') }
export default { components: { ImageUploadGrid }, data() { return { postId: '', categories: [], form: { title: '', slug: '', content: '', cover_url: '', excerpt: '', category_id: null, is_public: true, is_published: true, tags: [] }, images: [], saving: false } }, computed: { categoryNames() { return ['未分类', ...this.categories.map((category) => category.name)] }, selectedCategoryName() { const category = this.categories.find((item) => item.id === this.form.category_id); return category ? category.name : '未分类' } }, onLoad(query) { this.postId = query.id || ''; this.load() }, methods: { async load() { try { const [categories, posts] = await Promise.all([getBlogCategories(), this.postId ? getMyBlogPosts() : Promise.resolve([])]); this.categories = Array.isArray(categories) ? categories : []; if (this.postId) { const post = posts.find((item) => String(item.id) === String(this.postId)); if (!post) throw new Error('not found'); this.form = { title: post.title || '', slug: post.slug || '', content: post.content || '', cover_url: post.cover_url || '', excerpt: post.excerpt || '', category_id: post.category ? post.category.id : null, is_public: Boolean(post.is_public), is_published: Boolean(post.is_published), tags: post.tags || [] }; if (post.cover_url) this.images = [{ id: 'cover', url: post.cover_url, localPath: post.cover_url, status: 'success', progress: 100 }] } } catch (error) { uni.showToast({ title: '文章读取失败或没有权限', icon: 'none' }) } }, chooseCategory(event) { const index = Number(event.detail.value); this.form.category_id = index ? this.categories[index - 1].id : null }, syncImages(items) { const image = items.find((item) => item.status === 'success' && item.url); this.form.cover_url = image ? image.url : '' }, async save() { if (this.saving) return; if (!this.form.title.trim() || !this.form.content.trim()) { uni.showToast({ title: '请填写标题和正文', icon: 'none' }); return } this.saving = true; try { const payload = { ...this.form, title: this.form.title.trim(), content: this.form.content.trim(), slug: this.form.slug || slug(this.form.title), excerpt: this.form.excerpt || this.form.content.trim().slice(0, 160) }; if (this.postId) await updateMyBlogPost(this.postId, payload); else await createMyBlogPost(payload); uni.showToast({ title: '已保存', icon: 'success' }); setTimeout(() => uni.navigateBack({ delta: 1 }), 500) } catch (error) { uni.showToast({ title: '保存失败，请检查博客权限', icon: 'none' }) } finally { this.saving = false } }, back() { uni.navigateBack({ delta: 1 }) } } }
</script>
<style scoped>.page{height:100vh;background:#f1eee5}.bar{height:calc(var(--status-bar-height) + 104rpx);padding:var(--status-bar-height) 28rpx 0;box-sizing:border-box;display:flex;align-items:center;justify-content:space-between;background:#fffdf8;color:#17211d;font-family:Georgia,'Songti SC',serif;font-size:27rpx;font-weight:700}.bar text:first-child{font-size:56rpx;line-height:52rpx}.bar text:last-child{color:#1d6347;font-family:inherit;font-size:22rpx}.scroll{height:calc(100vh - var(--status-bar-height) - 104rpx)}.content{padding:28rpx}.input,.picker,.textarea{width:100%;box-sizing:border-box;border-radius:22rpx;background:#fffdf8;color:#17211d}.input{height:88rpx;padding:0 22rpx}.title{font-family:Georgia,'Songti SC',serif;font-size:30rpx;font-weight:700}.picker{margin-top:16rpx;padding:22rpx;color:#1d6347;font-size:22rpx}.textarea{min-height:450rpx;margin-top:16rpx;padding:22rpx;font-size:23rpx;line-height:38rpx}.switch-row{margin-top:16rpx;padding:20rpx;display:flex;align-items:center;justify-content:space-between;border-radius:20rpx;background:#e4ecdf;color:#163a2b;font-size:22rpx}.hint{display:block;margin-top:18rpx;color:rgba(23,33,29,.46);font-size:19rpx;line-height:30rpx}.primary{height:86rpx;margin-top:24rpx;border-radius:22rpx;color:#fff;background:#163a2b;font-size:24rpx;font-weight:700}.primary:after{border:none}</style>
